/* ==========================================================================
   Sri Shakthi Institute of Engineering and Technology - Compact Footer Styles
   ========================================================================== */

/* 1. Reset background: Clean dark forest-green linear gradient, zero circular glows */
.site-footer.footer-reference {
  margin: 0 !important;
  padding: 0 clamp(24px, 3.2vw, 56px) 0 !important;
  background: linear-gradient(118deg, #003f27, #00331f 58%, #00412a) !important;
  border-top: 6px solid #f3c515 !important;
  box-sizing: border-box !important;
}

.footer-reference .footer-legal::before,
.footer-reference .footer-legal::after,
.footer-reference .footer-legal small::before,
.footer-reference .footer-legal small::after {
  content: none !important;
  display: none !important;
}

/* 2. Desktop Grid Layout: Branding + Location (left), 6 Navigation Columns (right) */
@media (min-width: 1201px) {
  .footer-reference .footer-top {
    display: grid !important;
    grid-template-columns: minmax(470px, 520px) minmax(0, 1fr) !important;
    gap: 32px !important;
    padding: 28px 0 22px !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14) !important;
    align-items: start !important;
    box-sizing: border-box !important;
  }

  .footer-reference .footer-brand {
    min-width: 0 !important;
    padding-right: 0 !important;
    border-right: 0 !important;
    overflow: visible !important;
  }

  .footer-reference .footer-sitemap {
    display: grid !important;
    grid-template-columns: repeat(6, minmax(0, 1fr)) !important;
    gap: 0 !important;
    min-width: 0 !important;
    align-items: start !important;
  }
}

/* 3. College Logo & Branding */
.footer-reference .footer-brand .mark {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 14px !important;
  width: 100% !important;
  color: #ffffff !important;
  text-decoration: none !important;
  margin-bottom: 14px !important;
}

.footer-reference .footer-brand .mark > img {
  display: block !important;
  width: 60px !important;
  height: 60px !important;
  max-width: none !important;
  object-fit: contain !important;
  flex: 0 0 60px !important;
}

.footer-reference .footer-brand .mark > span {
  display: flex !important;
  flex-direction: column !important;
  gap: 2px !important;
  max-width: 100% !important;
}

.footer-reference .footer-brand .mark b {
  font-family: "League Spartan", "Plus Jakarta Sans", sans-serif !important;
  font-size: 20px !important;
  font-weight: 800 !important;
  letter-spacing: 0.04em !important;
  line-height: 1.1 !important;
  color: #ffffff !important;
}

.footer-reference .footer-brand .mark small {
  font-family: "Montserrat", sans-serif !important;
  font-size: 10.5px !important;
  font-weight: 700 !important;
  letter-spacing: 0.04em !important;
  line-height: 1.25 !important;
  color: #f3c515 !important;
}

.footer-reference .footer-brand .mark em {
  font-family: "Montserrat", sans-serif !important;
  font-size: 9px !important;
  font-weight: 600 !important;
  letter-spacing: 0.05em !important;
  color: #d1e3d7 !important;
  font-style: normal !important;
}

/* 4. Map & Address Row: Grid layout (1fr 1fr = Equal Width), perfectly aligned heights */
.footer-location-section {
  display: grid !important;
  grid-template-columns: 1fr 1fr !important;
  gap: 12px !important;
  width: 100% !important;
  height: 230px !important;
  align-items: stretch !important;
  box-sizing: border-box !important;
}

/* Left: Map Card (~50% width) */
.footer-location-section .footer-map-card {
  width: 100% !important;
  height: 230px !important;
  max-height: 230px !important;
  min-height: 230px !important;
  margin: 0 !important;
  display: flex !important;
  box-sizing: border-box !important;
}

.footer-location-section .footer-map-link {
  display: block !important;
  position: relative !important;
  width: 100% !important;
  height: 100% !important;
  border-radius: 10px !important;
  border: 1.5px solid #f3c515 !important;
  overflow: hidden !important;
  background-color: #002b1b !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25) !important;
  text-decoration: none !important;
  cursor: pointer !important;
  box-sizing: border-box !important;
  transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease !important;
  -webkit-tap-highlight-color: transparent !important;
}

.footer-location-section .footer-map-link:hover {
  transform: translateY(-2px) !important;
  border-color: #ffe45c !important;
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.4) !important;
}

.footer-location-section .footer-map-link:focus-visible {
  outline: 3px solid #f3c515 !important;
  outline-offset: 3px !important;
}

.footer-location-section .footer-map-link picture,
.footer-location-section .footer-map-link .footer-map-img {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: 22% 35% !important;
  transition: transform 0.35s ease !important;
}

.footer-location-section .footer-map-link:hover .footer-map-img {
  transform: scale(1.03) !important;
}

.footer-location-section .footer-map-btn {
  position: absolute !important;
  bottom: 8px !important;
  left: 8px !important;
  right: auto !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  padding: 4px 8px !important;
  background: rgba(3, 42, 25, 0.94) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  border: 1px solid rgba(243, 197, 21, 0.6) !important;
  border-radius: 6px !important;
  color: #ffffff !important;
  font-family: "Montserrat", "Plus Jakarta Sans", sans-serif !important;
  font-size: 10.5px !important;
  font-weight: 700 !important;
  letter-spacing: 0.02em !important;
  line-height: 1.2 !important;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.4) !important;
  pointer-events: none !important;
  transition: background 0.2s ease, border-color 0.2s ease !important;
  white-space: nowrap !important;
}

.footer-location-section .footer-map-pin {
  width: 12px !important;
  height: 12px !important;
  flex-shrink: 0 !important;
  color: #f3c515 !important;
}

.footer-location-section .footer-map-btn-text {
  color: #ffffff !important;
}

/* Right: Address Card (~50% width) */
.footer-location-section .footer-address-card {
  width: 100% !important;
  height: 230px !important;
  max-height: 230px !important;
  min-height: 230px !important;
  box-sizing: border-box !important;
  background: rgba(4, 52, 30, 0.94) !important;
  border: 1.5px solid #f3c515 !important;
  border-radius: 10px !important;
  padding: 12px 14px 10px !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: space-between !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25) !important;
  margin: 0 !important;
  transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease !important;
}

.footer-location-section .footer-address-card:hover {
  border-color: #ffe45c !important;
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.4) !important;
}

.footer-addr-header {
  display: flex !important;
  align-items: center !important;
  gap: 7px !important;
}

.footer-addr-icon-circle {
  width: 22px !important;
  height: 22px !important;
  border-radius: 50% !important;
  background: #f3c515 !important;
  color: #032a19 !important;
  display: grid !important;
  place-items: center !important;
  flex-shrink: 0 !important;
}

.footer-addr-title {
  margin: 0 !important;
  font-family: "League Spartan", "Plus Jakarta Sans", sans-serif !important;
  font-size: 13.5px !important;
  font-weight: 800 !important;
  letter-spacing: 0.03em !important;
  color: #f3c515 !important;
}

.footer-addr-divider {
  width: 100% !important;
  height: 1px !important;
  background: rgba(243, 197, 21, 0.35) !important;
  margin: 5px 0 6px !important;
}

.footer-addr-body {
  display: flex !important;
  align-items: flex-start !important;
  gap: 8px !important;
  flex-grow: 1 !important;
}

.footer-addr-pin-white {
  width: 15px !important;
  height: 15px !important;
  color: #ffffff !important;
  flex-shrink: 0 !important;
  margin-top: 1px !important;
}

.footer-addr-text {
  font-style: normal !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 1.5px !important;
  color: #ffffff !important;
  font-family: "Montserrat", "DM Sans", sans-serif !important;
  font-size: 10.5px !important;
  font-weight: 500 !important;
  line-height: 1.35 !important;
}

.footer-addr-actions {
  margin-top: 5px !important;
  padding-top: 5px !important;
  border-top: 1px solid rgba(243, 197, 21, 0.22) !important;
}

.footer-directions-btn {
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  color: #f3c515 !important;
  text-decoration: none !important;
  font-family: "Montserrat", "Plus Jakarta Sans", sans-serif !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  letter-spacing: 0.02em !important;
  transition: transform 0.2s ease, color 0.2s ease !important;
  cursor: pointer !important;
}

.footer-directions-btn:hover {
  color: #ffe45c !important;
  transform: translateX(2px) !important;
}

.footer-directions-btn:focus-visible {
  outline: 2px solid #f3c515 !important;
  outline-offset: 3px !important;
  border-radius: 4px !important;
}

.footer-directions-icon-circle {
  width: 22px !important;
  height: 22px !important;
  border-radius: 50% !important;
  background: #f3c515 !important;
  color: #032a19 !important;
  display: grid !important;
  place-items: center !important;
  flex-shrink: 0 !important;
  transition: transform 0.2s ease !important;
}

.footer-directions-btn:hover .footer-directions-icon-circle {
  transform: scale(1.08) !important;
}

/* 5. Navigation Columns: Top-aligned, compact vertical gaps, thin vertical dividers */
.footer-reference .footer-link-group {
  padding: 0 16px !important;
  border-right: 1px solid rgba(255, 255, 255, 0.12) !important;
  box-sizing: border-box !important;
  min-width: 0 !important;
}

.footer-reference .footer-link-group:last-child {
  border-right: 0 !important;
}

.footer-reference .footer-link-group > b {
  color: #f3c515 !important;
  font-family: "League Spartan", "Plus Jakarta Sans", sans-serif !important;
  font-size: 12.5px !important;
  font-weight: 800 !important;
  letter-spacing: 0.05em !important;
  text-transform: uppercase !important;
  min-height: auto !important;
  margin-bottom: 8px !important;
  display: block !important;
}

.footer-reference .footer-link-group > b:after {
  content: "" !important;
  display: block !important;
  width: 22px !important;
  height: 2px !important;
  margin-top: 6px !important;
  background: #f3c515 !important;
}

.footer-reference .footer-link-group > a {
  color: #f4f8f5 !important;
  font-size: 11.5px !important;
  font-weight: 500 !important;
  line-height: 1.35 !important;
  margin-bottom: 7px !important;
  display: block !important;
  transition: color 0.18s ease, transform 0.18s ease !important;
}

.footer-reference .footer-link-group > a:hover {
  color: #f3c515 !important;
  transform: translateX(2px) !important;
}

/* 6. Compact Legal / Copyright Section */
.footer-reference .footer-legal {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  padding: 14px 0 16px !important;
  min-height: auto !important;
  border-top: 1px solid rgba(255, 255, 255, 0.1) !important;
  box-sizing: border-box !important;
}

.footer-reference .footer-legal small {
  color: rgba(255, 255, 255, 0.8) !important;
  font-size: 11px !important;
  font-family: "Montserrat", sans-serif !important;
}

.footer-reference .footer-legal nav {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
}

.footer-reference .footer-legal nav a {
  color: rgba(255, 255, 255, 0.8) !important;
  font-size: 11px !important;
  font-family: "Montserrat", sans-serif !important;
  text-decoration: none !important;
  transition: color 0.2s ease !important;
}

.footer-reference .footer-legal nav a:hover {
  color: #f3c515 !important;
}

.footer-reference .footer-legal nav i {
  display: inline-block !important;
  width: 1px !important;
  height: 11px !important;
  background: #f3c515 !important;
}

/* 7. Tablet Layout (769px – 1200px) */
@media (max-width: 1200px) {
  .footer-reference .footer-top {
    grid-template-columns: 1fr !important;
    gap: 28px !important;
    padding-block: 28px 22px !important;
  }

  .footer-location-section {
    max-width: 480px !important;
    height: 220px !important;
  }

  .footer-location-section .footer-map-card,
  .footer-location-section .footer-address-card {
    height: 220px !important;
    max-height: 220px !important;
    min-height: 220px !important;
  }

  .footer-reference .footer-sitemap {
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
    gap: 24px 16px !important;
  }
}

/* 8. Mobile Layout (<= 768px) */
@media (max-width: 768px) {
  .footer-location-section {
    grid-template-columns: 1fr !important;
    height: auto !important;
    gap: 12px !important;
    max-width: 100% !important;
  }

  .footer-location-section .footer-map-card {
    height: 185px !important;
    max-height: 185px !important;
    min-height: 185px !important;
  }

  .footer-location-section .footer-address-card {
    height: auto !important;
    min-height: auto !important;
    max-height: none !important;
  }

  .footer-reference .footer-sitemap {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 24px 12px !important;
  }

  .footer-reference .footer-legal {
    flex-direction: column !important;
    align-items: flex-start !important;
    gap: 10px !important;
    padding-block: 14px !important;
  }
}

/* 9. Small Mobile (<= 480px) */
@media (max-width: 480px) {
  .footer-reference .footer-sitemap {
    grid-template-columns: 1fr !important;
    gap: 20px 0 !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .footer-map-link,
  .footer-map-img,
  .footer-address-card,
  .footer-directions-btn {
    transition: none !important;
    transform: none !important;
  }
}
